import os
from typing import Any, Dict, Optional
from urllib.parse import urlencode

import requests


class Auth0FederatedLoginFlow:
    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        client_secret: Optional[str] = None,
        redirect_uri: Optional[str] = None,
        session: Optional[requests.Session] = None,
    ) -> None:
        self.domain = (domain or os.getenv("AUTH0_DOMAIN", "")).strip()
        self.client_id = (client_id or os.getenv("AUTH0_CLIENT_ID", "")).strip()
        self.client_secret = (client_secret or os.getenv("AUTH0_CLIENT_SECRET", "")).strip()
        self.redirect_uri = (redirect_uri or os.getenv("AUTH0_REDIRECT_URI", "")).strip()
        self.session = session or requests.Session()

        if not self.domain:
            raise ValueError("AUTH0_DOMAIN is required")
        if not self.client_id:
            raise ValueError("AUTH0_CLIENT_ID is required")

        self.base_url = f"https://{self.domain}"

    def build_authorize_url(
        self,
        state: str,
        scope: str = "openid profile email",
        audience: Optional[str] = None,
        connection: Optional[str] = None,
        prompt: Optional[str] = None,
        response_type: str = "code",
    ) -> str:
        if not self.redirect_uri:
            raise ValueError("AUTH0_REDIRECT_URI is required to build authorize URL")

        params = {
            "response_type": response_type,
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": scope,
            "state": state,
        }
        if audience:
            params["audience"] = audience
        if connection:
            params["connection"] = connection
        if prompt:
            params["prompt"] = prompt

        return f"{self.base_url}/authorize?{urlencode(params)}"

    def exchange_code_for_tokens(self, code: str) -> Dict[str, Any]:
        if not self.client_secret:
            raise ValueError("AUTH0_CLIENT_SECRET is required to exchange authorization code")
        if not self.redirect_uri:
            raise ValueError("AUTH0_REDIRECT_URI is required to exchange authorization code")

        url = f"{self.base_url}/oauth/token"
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "client_secret": self.client_secret,
            "code": code,
            "redirect_uri": self.redirect_uri,
        }

        response = self.session.post(
            url,
            json=payload,
            headers={"Content-Type": "application/json"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json()

    def fetch_userinfo(self, access_token: str) -> Dict[str, Any]:
        url = f"{self.base_url}/userinfo"
        response = self.session.get(
            url,
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json()

    def normalize_claims(self, claims: Dict[str, Any]) -> Dict[str, Any]:
        raw_sub = claims.get("sub")
        identities = claims.get("identities") or []
        primary_identity = identities[0] if isinstance(identities, list) and identities else {}

        name = claims.get("name")
        given_name = claims.get("given_name")
        family_name = claims.get("family_name")
        nickname = claims.get("nickname")
        preferred_username = claims.get("preferred_username")

        normalized = {
            "provider": "auth0",
            "subject": raw_sub,
            "user_id": raw_sub,
            "email": claims.get("email"),
            "email_verified": _to_bool(claims.get("email_verified")),
            "phone_number": claims.get("phone_number"),
            "phone_number_verified": _to_bool(claims.get("phone_number_verified")),
            "name": name,
            "given_name": given_name,
            "family_name": family_name,
            "middle_name": claims.get("middle_name"),
            "nickname": nickname,
            "preferred_username": preferred_username,
            "picture": claims.get("picture"),
            "profile": claims.get("profile"),
            "website": claims.get("website"),
            "gender": claims.get("gender"),
            "birthdate": claims.get("birthdate"),
            "zoneinfo": claims.get("zoneinfo"),
            "locale": claims.get("locale"),
            "updated_at": claims.get("updated_at"),
            "federated_provider": primary_identity.get("provider"),
            "federated_connection": primary_identity.get("connection"),
            "federated_user_id": primary_identity.get("user_id"),
            "raw_claims": claims,
        }

        if not normalized["name"]:
            parts = [p for p in [given_name, family_name] if p]
            if parts:
                normalized["name"] = " ".join(parts)
            elif nickname:
                normalized["name"] = nickname
            elif preferred_username:
                normalized["name"] = preferred_username

        return normalized

    def fetch_and_normalize_profile(self, access_token: str) -> Dict[str, Any]:
        claims = self.fetch_userinfo(access_token)
        return self.normalize_claims(claims)

    def exchange_code_and_fetch_profile(self, code: str) -> Dict[str, Any]:
        tokens = self.exchange_code_for_tokens(code)
        access_token = tokens.get("access_token")
        if not access_token:
            raise ValueError("Auth0 token response did not include access_token")

        profile = self.fetch_and_normalize_profile(access_token)
        return {
            "tokens": tokens,
            "profile": profile,
        }


def _to_bool(value: Any) -> Optional[bool]:
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        v = value.strip().lower()
        if v in {"true", "1", "yes"}:
            return True
        if v in {"false", "0", "no"}:
            return False
    if isinstance(value, (int, float)):
        return bool(value)
    return None
